        assertNotNull(result);
    }

    @Test
    public void calculateSolarPositionWithZeroDeltaTTest() {
        ZonedDateTime date = ZonedDateTime.of(2020, 1, 1, 12, 0, 0, 0, ZoneOffset.UTC);
